class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def merge_two_sorted_lists(head1, head2):
    """合并两条递增单链表，返回合并后的头节点；只改指针，不新建节点。"""
    dummy = ListNode(0)          # 哨兵：统一「结果为空」与「已有尾节点」两种情况
    tail = dummy
    while head1 is not None and head2 is not None:
        if head1.val <= head2.val:   # 相等时只摘第一条链，保证不丢节点
            tail.next = head1
            head1 = head1.next
        else:
            tail.next = head2
            head2 = head2.next
        tail = tail.next             # 最常漏的一行：tail 必须跟着前移
    tail.next = head1 if head1 is not None else head2   # 剩余整段仍有序，O(1) 收尾
    return dummy.next


def build(vals):
    dummy = ListNode(0)
    cur = dummy
    for v in vals:
        cur.next = ListNode(v)
        cur = cur.next
    return dummy.next


def parse(text):
    """牛客格式 {1,3,5},{2,4,6} -> 两条链表；空段或 {} 表示空链表。"""
    parts = text.strip().split("},")
    if len(parts) != 2:
        raise ValueError("输入应形如 {1,3,5},{2,4,6}")

    def one(seg):
        seg = seg.strip().strip("{}").strip()
        if not seg:
            return None
        return build([int(x) for x in seg.split(",") if x.strip()])

    return one(parts[0]), one(parts[1])


def dump(head):
    vals = []
    while head is not None:
        vals.append(str(head.val))
        head = head.next
    return "{" + ",".join(vals) + "}"


if __name__ == "__main__":
    cases = [
        ("{1,3,5},{2,4,6}", "{1,2,3,4,5,6}"),
        ("{}, {}", "{}"),
        ("{-1,2,4},{1,3,4}", "{-1,1,2,3,4,4}"),
        ("{5,5},{5}", "{5,5,5}"),
        ("{}, {0}", "{0}"),
        ("{7},{1,2,3,4}", "{1,2,3,4,7}"),
    ]
    for text, want in cases:
        a, b = parse(text)
        got = dump(merge_two_sorted_lists(a, b))
        assert got == want, (text, got, want)
    print("all %d cases passed" % len(cases))
